package ai.eva.android.probe;
import java.nio.file.Path;
import android.app.Activity;import android.graphics.*;import android.graphics.pdf.*;import android.os.ParcelFileDescriptor;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.util.*;import org.json.*;
/** Real device checks on a unique workspace fixture; never edits user files. */
final class WorkspaceEditingProbe {
 interface Action{void run()throws Exception;}
 static void require(boolean ok,String message)throws IOException{if(!ok)throw new IOException(message);}
 static void rejects(Action action,String message)throws Exception{boolean blocked=false;try{action.run();}catch(IOException expected){blocked=true;}require(blocked,message);}
 static void check(Activity activity){new Thread(()->{JSONObject out=new JSONObject();Path fixture=null;long start=android.os.SystemClock.elapsedRealtime();try{
  Path root=WorkspaceFiles.root(activity).toPath();Path projects=root.resolve("projects");Files.createDirectories(projects);fixture=Files.createTempDirectory(projects,"editor-check-");final WorkspaceEditor store=new WorkspaceEditor(fixture.toFile());
  store.create("中文目录","",true);String name="中文目录/验收.md";store.create(name,"中文 😀\n",false);WorkspaceEditor.Document first=store.read(name);require(first.text.equals("中文 😀\n"),"UTF8 create/read mismatch");WorkspaceEditor.Document changed=store.save(name,"保存成功 😀\n",first.revision);require(changed.text.equals("保存成功 😀\n"),"Save mismatch");out.put("utf8CreateReadSave",true);
  rejects(()->store.save(name,"stale",first.revision),"Stale write allowed");Files.write(store.root.resolve(name),"agent update".getBytes(StandardCharsets.UTF_8));rejects(()->store.save(name,"lost update",changed.revision),"External update overwritten");require(store.read(name).text.equals("agent update"),"Conflict altered file");out.put("conflictPreservesAgentUpdate",true);
  rejects(()->store.create(name,"duplicate",false),"Duplicate accepted");rejects(()->store.create("../escape.txt","escape",false),"Traversal accepted");rejects(()->store.create("/outside.txt","escape",false),"Absolute path accepted");out.put("duplicateAndTraversalRejected",true);
  Files.write(store.root.resolve("invalid.txt"),new byte[]{(byte)0xc3,0x28});Files.write(store.root.resolve("binary.bin"),new byte[]{65,0,66});rejects(()->store.read("invalid.txt"),"Malformed UTF8 accepted");rejects(()->store.read("binary.bin"),"Binary accepted");out.put("invalidTextRejected",true);
  byte[] huge=new byte[WorkspaceEditor.MAX_BYTES+1];Arrays.fill(huge,(byte)'x');Files.write(store.root.resolve("large.txt"),huge);rejects(()->store.read("large.txt"),"Oversize accepted");out.put("sizeBoundEnforced",true);
  Files.createSymbolicLink(store.root.resolve("file-link"),store.root.resolve(name));Files.createSymbolicLink(store.root.resolve("dir-link"),store.root.resolve("中文目录"));rejects(()->store.read("file-link"),"File symlink accepted");rejects(()->store.create("dir-link/blocked.txt","bad",false),"Directory symlink accepted");require(!Files.exists(store.root.resolve("中文目录/blocked.txt")),"Symlink wrote target");out.put("androidSymlinkRejected",true);
  store.create("run.sh","#!/bin/sh\necho before\n",false);java.util.Set<java.nio.file.attribute.PosixFilePermission> mode=java.nio.file.attribute.PosixFilePermissions.fromString("rwxr-xr-x");Files.setPosixFilePermissions(store.root.resolve("run.sh"),mode);WorkspaceEditor.Document script=store.read("run.sh");store.save("run.sh","#!/bin/sh\necho after\n",script.revision);require(Files.getPosixFilePermissions(store.root.resolve("run.sh")).equals(mode),"Save removed executable mode");out.put("executablePermissionsPreserved",true);
  File pdfFile=store.root.resolve("preview.pdf").toFile();PdfDocument document=new PdfDocument();try{for(int i=0;i<2;i++){PdfDocument.Page page=document.startPage(new PdfDocument.PageInfo.Builder(300,400,i+1).create());Paint paint=new Paint();paint.setColor(Color.BLACK);paint.setTextSize(22);page.getCanvas().drawColor(Color.WHITE);page.getCanvas().drawRect(10,10,80,80,paint);page.getCanvas().drawText("Eva page "+(i+1),10,120,paint);document.finishPage(page);}try(OutputStream stream=new FileOutputStream(pdfFile)){document.writeTo(stream);}}finally{document.close();}
  try(ParcelFileDescriptor descriptor=ParcelFileDescriptor.open(pdfFile,ParcelFileDescriptor.MODE_READ_ONLY);PdfRenderer renderer=new PdfRenderer(descriptor)){require(renderer.getPageCount()==2,"PDF page count mismatch");for(int i=0;i<2;i++)try(PdfRenderer.Page page=renderer.openPage(i)){Bitmap bitmap=Bitmap.createBitmap(300,400,Bitmap.Config.ARGB_8888);try{bitmap.eraseColor(Color.WHITE);page.render(bitmap,null,null,PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY);require(Color.red(bitmap.getPixel(30,30))<100,"PDF page did not render content");}finally{bitmap.recycle();}}}out.put("nativeTwoPagePdfRender",true);
  try(java.util.stream.Stream<Path> stream=Files.walk(store.root)){require(stream.noneMatch(p->p.getFileName().toString().startsWith(".eva-edit-")),"Temporary edit files left");}out.put("atomicSaveCleanup",true).put("result","PASS");
 }catch(Exception e){try{out.put("result","FAIL").put("error",e.toString());}catch(Exception ignored){}}
 finally{boolean clean=true;if(fixture!=null){try{Path projects=WorkspaceFiles.root(activity).toPath().resolve("projects");require(fixture.getParent().equals(projects)&&fixture.getFileName().toString().startsWith("editor-check-"),"Cleanup boundary mismatch");try(java.util.stream.Stream<Path> stream=Files.walk(fixture)){for(Path p:(Iterable<Path>)stream.sorted(Comparator.reverseOrder())::iterator)Files.delete(p);}}catch(Exception e){clean=false;try{out.put("cleanupError",e.toString());}catch(Exception ignored){}}}try{out.put("fixtureCleanup",clean).put("elapsedMs",android.os.SystemClock.elapsedRealtime()-start).put("uiLifecycleTested",false);if(!clean)out.put("result","FAIL");}catch(Exception ignored){}}
 activity.getSharedPreferences("eva-workspace-check",0).edit().putString("editing",out.toString()).commit();final String result=out.optString("result");activity.runOnUiThread(()->android.widget.Toast.makeText(activity,"Workspace check: "+result,1).show());
 },"eva-workspace-edit-check").start();}
}
